import java.io.*;import java.nio.file.*;import java.nio.file.attribute.*;import java.util.stream.*;
public class Main {public static void main(String[] args)throws IOException{Path root=Paths.get("sample-logs"),report=Paths.get("folder-report.txt");Files.createDirectories(root);try(BufferedWriter w=Files.newBufferedWriter(report);Stream<Path> paths=Files.walk(root)){for(Path p:(Iterable<Path>)paths.filter(Files::isRegularFile)::iterator){BasicFileAttributes a=Files.readAttributes(p,BasicFileAttributes.class);w.write(p.getFileName()+" | "+a.size()+" bytes | "+a.lastModifiedTime());w.newLine();}}System.out.println("Folder report saved to "+report);}}
